/* Design tokens: "The Creative Facilitator" -- warm and creative, on a serious, high-contrast structure.
   Cream Linen canvas (60%), Soft Sand zones (30%), Midnight Espresso text, Apricot Glow for actions only (10%),
   Earthy Coral for alerts and active highlights. Accent *fills* carry Espresso text; accent *text* uses the deeper
   "ink" shade, because Apricot itself is 2:1 on Cream (every text pair below is at least 4.5:1).
   Variable names are kept from the earlier passes so every component keeps working. */

:root {
  color-scheme: light;

  /* ---- palette */
  --linen: #FAF8F5;             /* Cream Linen: app canvas and raised items inside zones */
  --sand: #EFECE6;              /* Soft Sand: structural zones (panels, sidebars, report) */
  --espresso: #1C1917;          /* Midnight Espresso: text and navigation (16.5:1 on Linen, 14.8:1 on Sand) */
  --apricot: #F59E0B;           /* Apricot Glow: primary actions, success, focal points (fills only) */
  --apricot-ink: #92400E;       /* Apricot as text or icon (6.7:1 on Linen, 6.0:1 on Sand) */
  --coral: #DC2626;             /* Earthy Coral: alerts, notifications, active highlights (fills, white text 4.8:1) */
  --coral-ink: #B91C1C;         /* Coral as text, safe on Sand too */
  --raised: var(--linen);       /* items sitting on a Sand zone */
  --zone: var(--sand);

  /* ---- colour roles */
  --cta: var(--apricot-ink);    /* accent text, links, icons */
  --cta-fill: var(--apricot);   /* primary buttons, pressed toggles */
  --on-cta: var(--espresso);    /* text on an Apricot fill (8.1:1) */
  --cta-hover: #E08E0A;
  --cta-disabled: #F3DDB0;
  --cta-soft: #FDF0D5;
  --cta-border: #F2C46D;
  --nba: #1C1917;               /* dark secondary button */
  --nba-hover: #44403C;
  --nba-disabled: #D6D3CE;
  --heading: #1C1917;
  --copy-text: #1C1917;
  --text-2: #57534E;            /* 6.5:1 on Sand */
  --disclaimer: #6B6359;        /* 5.0:1 on Sand */
  --surface-background-primary: var(--linen);
  --surface-background-secondary: var(--sand);
  --neutral-background: #E6E1D8;
  --border: #E2DCD1;
  --input-border-color: #B5ADA1;
  --input-border-color-hover: #8C847A;
  --filtertag: #E6E1D8;
  --filtertag-selected: var(--apricot);
  --error: var(--coral-ink);
  --error-fill: var(--coral);
  --error-background: #FBE9E7;
  --warning: var(--coral-ink);  /* alerts and "your turn" highlights are Coral; the text says which */
  --warning-fill: var(--coral);
  --warning-background: #FCEFEC;
  --success: var(--apricot-ink);
  --success-fill: var(--apricot);
  --success-background: #FDF3E1;
  --information: #57534E;
  --information-background: #F5F1EA;
  --violet: #7c3aed;
  --violet-background: #f5f3ff;
  --stage: var(--linen);

  /* ---- shape and depth */
  --radius-control: 10px;
import { useEffect, useLayoutEffect, useRef, useState, type ReactNode } from "react";
import { MARKET_NAMES, MODEL_NAMES, fmtInt, fmtNum } from "../api";
import type { AgentEvaluation, AgentStatus, Explained, IdeaSpec, InterpretResult } from "../types";
import { REC_INFO, REC_ORDER, bottomLine, complaintReason, groupCells, placesText, type RecGroup } from "../plain";

// The pipeline as a horizontal flowchart. The backend answers in three blocking requests
// (interpret, evaluate, explain), so a card shows "running" with the real elapsed time while its
// request is open, and its child nodes appear only when that response arrives. Nothing is simulated.

export type Phase = "idle" | "interpreting" | "review" | "evaluating" | "done";
export type ExplainState = "idle" | "running" | "done" | "unavailable" | "error" | "stale";
export type RunKey = "interpret" | "evaluate" | "explain";
export interface RunTiming {
  start: number;          // performance.now() when the request was sent
  end?: number;           // when the response (or the error) arrived
  failed?: boolean;
}
export type Runs = Partial<Record<RunKey, RunTiming>>;

export type StepId = "retriever" | "you" | "engine" | "explainer" | "verifier" | "brief";
export type Actor = StepId | "system" | "analyst" | "presenter";
export interface TraceEvent {
  id: number;
  at: number;             // performance.now()
  clock: string;          // wall-clock time, HH:MM:SS
  actor: Actor;
  title: string;
  detail?: string;
  tone?: "wait" | "error" | "stale";
}

type NodeState = "waiting" | "running" | "wait" | "done" | "off" | "error" | "stale";
type Tone = "ok" | "warn" | "fail" | "info";
interface Line {
  text: string;
  status?: "ok" | "fail" | "skip" | "info";
}
interface Kid {
  key: string;
  label: string;
  sub?: string;
  tone?: Tone;
  body: ReactNode;
}
interface FlowNode {
  id: StepId;
  title: string;
  who: string;
  state: NodeState;
  run?: RunTiming;
  about: string;          // what the step does
  summary?: string;       // one line on the card once it has a result
  lines: Line[];          // what it actually did (popup)
  kids: Kid[];            // child nodes added from the response
  handover?: string;
  note?: string;
}

const MAX_KIDS = 3;

const STATE_TEXT: Record<NodeState, string> = {
  waiting: "Not started", running: "Running", wait: "Your turn", done: "Done", off: "Not available", error: "Failed", stale: "Out of date",
};

export const ACTOR_LABEL: Record<Actor, string> = {
  you: "You", retriever: "Retriever agent", engine: "Decision engine", explainer: "Explainer agent", verifier: "Verifier agent",
  brief: "Brief", system: "System", analyst: "Competitor analyst", presenter: "Presenter agent",
};

const RULE_TEXT: Record<string, string> = {
  citations: "Each sentence cites at least one fact, and every cited fact exists.",
  numbers: "Every number in the sentence equals a value in a cited fact.",
  labels: "Labels such as 'Consider' or 'Mixed' appear in a cited fact.",
  quotes: "Quoted text is copied word for word from a cited customer comment.",
  scope: "Every series and market the sentence names is covered by a cited fact.",
  semantic: "A language model judges whether the cited facts really support the sentence.",
};

const ICON_PATHS: Record<Actor, ReactNode> = {
  you: (<><circle cx="12" cy="8" r="3.4" /><path d="M5 20c0-3.6 3.1-6 7-6s7 2.4 7 6" /></>),
