<!doctype html><html><head><meta charset="utf-8"><title>Decision Studio film</title>
<style>
@font-face{font-family:BMWN;src:url(assets/fonts/BMWTypeNext-Light.woff2);font-weight:300}
@font-face{font-family:BMWN;src:url(assets/fonts/BMWTypeNext-Regular.woff2);font-weight:400}
@font-face{font-family:BMWN;src:url(assets/fonts/BMWTypeNext-Medium.woff2);font-weight:500}
@font-face{font-family:BMWN;src:url(assets/fonts/BMWTypeNext-Bold.woff2);font-weight:700}
:root{--linen:#FAF8F5;--sand:#EFECE6;--esp:#1C1917;--apr:#F59E0B;--aprink:#92400E;--coral:#DC2626;--coralink:#B91C1C;--t2:#57534E;--bd:#E2DCD1;--aprsoft:#FDF0D5}
*{box-sizing:border-box;margin:0}
html,body{background:#111;width:100%;height:100%;overflow:hidden}
#stage{position:relative;width:1920px;height:1080px;background:var(--linen);overflow:hidden;font-family:BMWN,system-ui;color:var(--esp)}
.sc{position:absolute;inset:0;opacity:0}
.abs{position:absolute}
.cap{position:absolute;left:110px;top:92px;font-size:22px;letter-spacing:.14em;text-transform:uppercase;color:var(--aprink);font-weight:500}
.h1{position:absolute;left:110px;font-size:58px;font-weight:300;line-height:1.12;letter-spacing:-.01em;white-space:nowrap}
.h1 b{font-weight:500}
.tag{display:inline-block;font-size:17px;font-weight:500;padding:5px 12px;border-radius:99px;letter-spacing:.02em;white-space:nowrap}
.t-obs{background:var(--esp);color:var(--linen)}
.t-ass{background:var(--aprsoft);color:var(--aprink);border:1.5px solid #F2C46D}
.t-scn{background:transparent;color:var(--t2);border:1.5px dashed var(--t2)}
.card{position:absolute;background:var(--sand);border-radius:20px;padding:26px 30px}
.chip{display:inline-flex;align-items:center;gap:8px;background:var(--linen);border:1.5px solid var(--bd);border-radius:99px;padding:8px 18px;font-size:24px;white-space:nowrap}
.btn{position:absolute;background:var(--apr);color:var(--esp);font-weight:500;font-size:26px;border-radius:99px;padding:16px 38px}
#foot{position:absolute;left:110px;bottom:34px;font-size:15px;color:#8C847A;letter-spacing:.04em;z-index:99}
#cursor{position:absolute;width:30px;height:30px;z-index:90;opacity:0}
</style></head><body>
<div id="stage">
 <!-- S1 problem -->
 <div class="sc" id="s1">
  <div class="abs" id="q" style="left:0;right:0;top:440px;text-align:center;font-size:76px;font-weight:300;letter-spacing:-.015em"></div>
  <div class="abs" id="caret" style="top:436px;width:4px;height:92px;background:var(--apr)"></div>
  <div class="abs" id="s1sub" style="left:0;right:0;top:580px;text-align:center;font-size:28px;color:var(--t2)">A product manager's question, three to five years before launch</div>
 </div>
 <!-- S2 retriever -->
 <div class="sc" id="s2">
  <div class="cap">1 · Retriever agent</div>
  <div class="h1" id="s2h" style="top:150px">Reads the question. <b>Picks only from features found in code.</b></div>
  <div class="abs" id="s2q" style="left:110px;top:330px;font-size:34px;color:var(--t2);font-weight:300">"Should we add a head-up display to the next vehicle line?"</div>
  <div class="abs" id="s2c1" style="left:110px;top:440px"><div style="font-size:18px;color:var(--t2);margin-bottom:10px;letter-spacing:.1em">FEATURE</div><span class="chip" style="font-size:40px;padding:16px 34px;background:var(--aprsoft);border-color:#F2C46D">Head-Up Display</span></div>
  <div class="abs" id="s2c2" style="left:640px;top:440px"><div style="font-size:18px;color:var(--t2);margin-bottom:10px;letter-spacing:.1em">DOMAIN</div><span class="chip" style="font-size:40px;padding:16px 34px">Infotainment &amp; HMI</span></div>
  <div class="abs" id="s2c3" style="left:1230px;top:440px"><div style="font-size:18px;color:var(--t2);margin-bottom:10px;letter-spacing:.1em">SERIES</div><span class="chip" style="font-size:40px;padding:16px 34px">F70</span> <span class="chip" style="font-size:40px;padding:16px 34px">G60</span> <span class="chip" style="font-size:40px;padding:16px 34px">G70</span></div>
  <div class="abs" id="s2c4" style="left:110px;top:640px;font-size:30px;color:var(--t2);max-width:1300px;line-height:1.4">The language model extracts and classifies. It never calculates, and it cannot invent a feature that is not in the data.</div>
 </div>
 <!-- S3 you -->
 <div class="sc" id="s3">
  <div class="cap" style="color:var(--coralink)">2 · Your turn</div>
  <div class="h1" style="top:150px">AI proposes. <b>The PM decides.</b></div>
  <div class="card" id="s3card" style="left:110px;top:330px;width:1100px;height:460px;background:var(--linen);border:2.5px solid var(--coral)">
    <div style="display:flex;justify-content:space-between;align-items:center"><div style="font-size:30px;font-weight:500">Extracted idea spec</div><span class="tag" style="background:var(--coral);color:#fff" id="s3tag">Your turn: confirm</span></div>
    <div style="margin-top:34px;font-size:30px;line-height:2.1;color:var(--t2)">
     <div>Feature <b style="color:var(--esp);font-weight:500;margin-left:30px">Head-Up Display</b></div>
     <div>Series <b style="color:var(--esp);font-weight:500;margin-left:46px">F70 · G60 · G70</b></div>
     <div>Markets <b style="color:var(--esp);font-weight:500;margin-left:22px">EU · US · CN · RoW</b></div>
    </div>
  </div>
  <div class="btn" id="s3btn" style="left:830px;top:700px">Confirm spec</div>
  <div class="abs" id="s3ok" style="left:130px;top:706px;font-size:28px;color:var(--aprink);font-weight:500;opacity:0">Confirmed. Applying it creates a new run.</div>
 </div>
 <!-- S4 engine -->
 <div class="sc" id="s4">
  <div class="cap">3 · Decision engine</div>
  <div class="h1" style="top:150px">Deterministic code calculates. <b>The LLM never does.</b></div>
  <div class="abs" id="s4w" style="left:110px;top:290px;display:flex;gap:16px;align-items:center;font-size:22px;color:var(--t2)">
    <span>Weights</span><span class="chip" style="font-size:22px">Complaints 0.40</span><span class="chip" style="font-size:22px">Breadth 0.20</span><span class="chip" style="font-size:22px">Requests 0.20</span><span class="chip" style="font-size:22px">Survey 0.20</span><span class="tag t-ass">assumption · policy v1.0</span>
  </div>
  <div class="abs" id="grid" style="left:110px;top:370px;width:1700px"></div>
  <div class="abs" id="s4head" style="left:110px;top:900px;font-size:36px;font-weight:300"></div>
 </div>
 <!-- S5 explainer -->
 <div class="sc" id="s5">
